async def act(page):
    """
    From the current New Rule page, open the Actions panel, set the "Apply" type
    to a fixed-cart discount, set Discount Amount to 10, select all customer groups,
    then save the rule.
    """
    # Click the Actions link to reveal the Actions section (present in the accessibility tree)
    actions_link = page.get_by_role("link", name="Actions")
    if await actions_link.count() > 0:
        await actions_link.first.click()
        # small pause to allow the Actions region to render
        await page.wait_for_timeout(600)

    # Helper: select an option from any combobox whose options contain a substring
    async def select_combobox_option_by_substring(substring: str) -> bool:
        cbs = page.get_by_role("combobox")
        cb_count = await cbs.count()
        for i in range(cb_count):
            cb = cbs.nth(i)
            opts_locator = cb.get_by_role("option")
            try:
                opts = await opts_locator.all_inner_texts()
            except Exception:
                opts = []
            for opt in opts:
                if substring.lower() in opt.lower():
                    try:
                        # Prefer selecting by the exact visible label
                        await cb.select_option(label=opt)
                        return True
                    except Exception:
                        # Narrow fallback: try selecting by matching value
                        try:
                            values = await opts_locator.evaluate_all("els => els.map(e => e.value)")
                            for idx, text in enumerate(opts):
                                if substring.lower() in text.lower():
                                    await cb.select_option(value=values[idx])
                                    return True
                        except Exception:
                            pass
        return False

    # Try to set Apply => fixed-cart discount using a sequence of likely labels
    for candidate in [
        'Fixed amount discount for whole cart',
        'Fixed amount discount for cart',
        'Fixed amount discount',
        'Fixed',
    ]:
        ok = await select_combobox_option_by_substring(candidate)
        if ok:
            break

    # Ensure all customer groups are selected (listbox visible in the accessibility tree)
    cg_listbox = page.get_by_role('listbox', name='Customer Groups *')
    if await cg_listbox.count() == 0:
        cg_listbox = page.get_by_role('listbox', name='Customer Groups')
    if await cg_listbox.count() > 0:
        # Select all known options by their visible labels exactly as they appear in the tree
        labels = [
            'NOT LOGGED IN',
            'General',
            'Wholesale',
            'VIP Member',
            'Private Sales Member',
        ]
        select_args = [{ 'label': lab } for lab in labels]
        try:
            await cg_listbox.first.select_option(select_args)
        except Exception:
            # Fallback: try selecting by matching option values for options that contain the label substrings
            opts_locator = cg_listbox.first.get_by_role('option')
            try:
                opts = await opts_locator.all_inner_texts()
                values = await opts_locator.evaluate_all("els => els.map(e => e.value)")
                chosen_values = []
                for idx, text in enumerate(opts):
                    if any(lab.lower() in text.lower() for lab in labels):
                        chosen_values.append(values[idx])
                if chosen_values:
                    await cg_listbox.first.select_option(chosen_values)
            except Exception:
                pass

    # Set Discount Amount to 10. Try common accessible names and roles.
    discount_locator = page.get_by_role('textbox', name='Discount Amount')
    if await discount_locator.count() == 0:
        discount_locator = page.get_by_role('textbox', name='Discount')
    if await discount_locator.count() == 0:
        discount_locator = page.get_by_role('spinbutton', name='Discount Amount')
    if await discount_locator.count() == 0:
        discount_locator = page.get_by_role('spinbutton', name='Discount')

    if await discount_locator.count() > 0:
        await discount_locator.first.fill('10')
    else:
        # fallback: fill the first textbox on the page (best-effort)
        textboxes = page.get_by_role('textbox')
        tb_count = await textboxes.count()
        for i in range(tb_count):
            tb = textboxes.nth(i)
            try:
                await tb.fill('10')
                break
            except Exception:
                continue

    await page.wait_for_timeout(300)

    # Save the rule - this is expected to submit and likely navigate, so make it the last action
    save_btn = page.get_by_role('button', name='Save')
    if await save_btn.count() > 0:
        await save_btn.first.click()
    else:
        # fallback: click the first button whose visible text contains 'save'
        all_buttons = page.get_by_role('button')
        btn_count = await all_buttons.count()
        for i in range(btn_count):
            b = all_buttons.nth(i)
            try:
                texts = await b.all_inner_texts()
                if texts and any('save' in t.lower() for t in texts):
                    await b.click()
                    break
            except Exception:
                continue

    # allow time for save to process / navigation to occur
    await page.wait_for_timeout(1500)
